import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Crimson/SeaStore 2021-09-01","description":"","frontmatter":{"title":"Ceph Crimson/SeaStore 2021-09-01","date":"2021-09-01T00:00:00.000Z","updated":"2021-09-02T00:00:00.000Z","tags":["Ceph","Distributed Storage","Performance Optimization","C","Store","Rook Integration"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Crimson_SeaStore_2021-09-01.md","filePath":"posts/2021/Ceph_Crimson_SeaStore_2021-09-01.md","lastUpdated":1780459816000}'),a={name:"posts/2021/Ceph_Crimson_SeaStore_2021-09-01.md"};function l(n,o,s,d,h,C){return t(),r("div",null,[...o[0]||(o[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="主要议题与讨论内容" tabindex="-1">主要议题与讨论内容 <a class="header-anchor" href="#主要议题与讨论内容" aria-label="Permalink to &quot;主要议题与讨论内容&quot;">​</a></h4><ol><li><strong>LBA重写合并</strong>：本周LBA重写已合并，但遇到断言失败问题，Yang Zum、Chun Mei和会议主持人均能复现，正在寻找问题根源。</li><li><strong>多核利用率</strong>：会议主持人正在研究代码和文档，尝试提高多核利用率，并已提交几个小规模Pull Request（PR）。</li><li><strong>性能分析</strong>：Chad May报告了文件性能分析结果，指出在某些情况下，性能比Ceph的BlueStore更差，计划获取操作周期数并进行优化。</li><li><strong>C-Store优化</strong>：讨论了C-Store在高负载下的性能问题，建议使用OProfile等性能分析工具来识别CPU热点，以便进行优化。</li><li><strong>Rook集成</strong>：Radik报告了Rook集成的进展，包括添加了Ammon Host Override选项，并解决了序列化器的内存管理问题。</li><li><strong>新成员介绍</strong>：Moreno作为新成员加入，表示正在了解会议内容和项目情况。</li><li><strong>Crimson项目资源</strong>：讨论了Crimson项目的资源和支持，Intel计划在下一季度增加资源。</li><li><strong>多设备支持</strong>：会议主持人正在开发多设备支持，特别是修改段清理器的行为以适应多设备。</li><li><strong>性能分析工具</strong>：讨论了使用OProfile等工具进行性能分析，以识别C-Store的CPU热点。</li><li><strong>内存管理</strong>：讨论了Rook集成中的内存管理问题，Radik解决了序列化器的一些内存管理问题。</li><li><strong>C-Store基本存储算法</strong>：指出C-Store在基本存储算法上缺乏优化，如长生命周期扩展的写入和垃圾收集。</li><li><strong>Crimson项目进展</strong>：讨论了Crimson项目的进展，包括性能优化和资源投入。</li><li><strong>段清理器</strong>：讨论了段清理器的行为和多设备支持。</li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>使用OProfile等性能分析工具来识别C-Store的CPU热点。</li><li>继续优化C-Store的基本存储算法，特别是关于数据写入和垃圾收集的部分。</li><li>提交小规模的PR以加速合并过程。</li><li>解决Rook集成中的内存管理问题。</li><li>开发多设备支持，特别是修改段清理器的行为以适应多设备。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续进行性能分析和优化工作。</li><li>提交小规模的PR以改进多设备支持。</li><li>新成员Moreno将继续了解项目和会议内容。</li><li>关注Intel对Crimson项目的资源投入。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>会议主持人提醒，Beast现在默认不显示损坏信息，如果需要在前台运行，可以使用Crimson Foreground选项。</li></ul><p>会议结束时，所有参与者表示感谢并期待下次会议。</p>',10)])])}const m=e(a,[["render",l]]);export{_ as __pageData,m as default};
